328	class DijkstraShortestPathSolver {
329	    private static final int INFINITY = Integer.MAX_VALUE;
330	
331	    ShortestPathResult solve(WeightedGraphView graph, int sourceNode) {
332	        Objects.requireNonNull(graph, "Graph cannot be null");
333	        validateSourceNode(graph, sourceNode);
334	
335	        DistanceTable distanceTable = DistanceTable.create(graph.getVertexCount(), sourceNode);
336	        int[] predecessors = initializePredecessors(graph.getVertexCount());
337	        PriorityQueue<PriorityQueueEntry> priorityQueue = new PriorityQueue<>();
338	        priorityQueue.offer(PriorityQueueEntry.of(0, sourceNode));
339	
340	        processQueue(graph, distanceTable, predecessors, priorityQueue);
341	
342	        List<Integer> distances = convertToList(distanceTable.toArray());
343	        return ShortestPathResult.of(distances, predecessors, sourceNode, graph);
344	    }
345	
346	    private void processQueue(WeightedGraphView graph, DistanceTable distanceTable,
347	                              int[] predecessors, PriorityQueue<PriorityQueueEntry> priorityQueue) {
348	        while (!priorityQueue.isEmpty()) {
349	            processQueueEntry(graph, distanceTable, predecessors, priorityQueue);
350	        }
351	    }
352	
353	    private void processQueueEntry(WeightedGraphView graph, DistanceTable distanceTable,
354	                                   int[] predecessors, PriorityQueue<PriorityQueueEntry> priorityQueue) {
355	        PriorityQueueEntry current = priorityQueue.poll();
356	        int currentNode = current.getNode();
357	        int currentDistance = current.getDistance();
358	
359	        if (isOutdatedEntry(currentDistance, distanceTable.getDistance(currentNode))) {
360	            return;
361	        }
362	
363	        graph.getAdjacencyListFor(currentNode).forEach(
364	            edge -> relaxEdge(distanceTable, predecessors, currentNode, edge, priorityQueue)
365	        );
366	    }
367	
368	    private boolean isOutdatedEntry(int entryDistance, int currentDistance) {
369	        return entryDistance > currentDistance;
370	    }
371	
372	    private void relaxEdge(DistanceTable distanceTable, int[] predecessors, int currentNode,
373	                          Edge edge, PriorityQueue<PriorityQueueEntry> priorityQueue) {
374	        int neighbor = edge.getDestination();
375	        int weight = edge.getWeight();
376	        int newDistance = distanceTable.getDistance(currentNode) + weight;
377	
378	        if (newDistance < distanceTable.getDistance(neighbor)) {
379	            distanceTable.updateDistance(neighbor, newDistance);
380	            predecessors[neighbor] = currentNode;
381	            priorityQueue.offer(PriorityQueueEntry.of(newDistance, neighbor));
382	        }
383	    }
384	
385	    private int[] initializePredecessors(int vertexCount) {
386	        int[] predecessors = new int[vertexCount];
387	        Arrays.fill(predecessors, -1);
388	        return predecessors;
389	    }
390	
391	    private List<Integer> convertToList(int[] distances) {
392	        return new ArrayList<>(Arrays.asList(
393	            Arrays.stream(distances).boxed().toArray(Integer[]::new)
394	        ));
395	    }
